from packaging.version import Version

def newest_compatible(versions: list[str], minimum: str) -> str | None:
    min_ver = Version(minimum)
    compatible_versions = [v for v in versions if Version(v) >= min_ver]
    if not compatible_versions:
        return None
    # Return the version string with the highest Version object
    return max(compatible_versions, key=Version)

